import React, { useState } from 'react';

const questions = [
  { id:1, text:'Как часто вы чувствуете напряжение в течение дня?', options:['Почти не чувствую','Иногда','Часто','Почти всегда'] },
  { id:2, text:'Что сейчас ощущаете сильнее всего?', options:['Тревога','Усталость','Раздражительность','Эмоциональное опустошение'] },
  { id:3, text:'Как вы обычно справляетесь со стрессом?', options:['Отвлекаюсь (соцсети, сериалы)','Разговариваю с кем-то','Стараюсь игнорировать','Не знаю, сложно справляться'] },
  { id:4, text:'Хотели бы вы получать поддержку и разбор ваших мыслей 24/7?', options:['Да','Скорее да','Скорее нет','Нет'] }
];

const Test = ({ id, go, setTestAnswers }) => {
  const [idx, setIdx] = useState(0);
  const [answers, setAnswers] = useState(Array(questions.length).fill(null));

  const handleSelect = (i) => {
    const copy = [...answers]; copy[idx] = i; setAnswers(copy);
  };

  const next = () => {
    if(answers[idx]===null) return;
    if(idx < questions.length-1) setIdx(idx+1);
    else { setTestAnswers(answers); go('result'); }
  };

  const prev = () => { if(idx>0)setIdx(idx-1); else go('welcome'); };

  const q = questions[idx];
  const progress = (idx/questions.length)*100;

  return (
    <div id={id} className="panel-container">
      <div className="progress-bar">
        <div className="progress-bar-fill" style={{width:`${progress}%`}}></div>
      </div>

      <div className="panel-title">{`Вопрос ${idx+1} из ${questions.length}`}</div>
      <div className="panel-subtitle">{q.text}</div>

      {q.options.map((opt,i)=>(
        <div key={i} className={`test-option ${answers[idx]===i?'selected':''}`} onClick={()=>handleSelect(i)}>
          {opt}
        </div>
      ))}

      <button className="button-main" onClick={next} disabled={answers[idx]==null}>
        {idx<questions.length-1?'Далее':'Показать результат'}
      </button>
      <button className="button-secondary" onClick={prev}>Назад</button>
    </div>
  );
};

export default Test;
