import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Pay = ({ id, go }) => {
  const [loading, setLoading] = useState(false);

  // Загружаем скрипт виджета ЮKassa
  useEffect(() => {
    const scriptId = "yookassa-widget";

    if (!document.getElementById(scriptId)) {
      const script = document.createElement("script");
      script.src = "https://yookassa.ru/checkout-widget/v1/checkout-widget.js";
      script.id = scriptId;
      script.async = true;
      document.body.appendChild(script);
    }
  }, []);

  const handlePayment = async () => {
    setLoading(true);

    try {
      // Создаём платеж
      const res = await axios.post('https://ser-hyfd.onrender.com/create-payment', {
        amount: 1,
        description: "Подписка Арины (1 месяц)"
      });

      const { paymentId, confirmation_token } = res.data;

      localStorage.setItem("arina_payment_id", paymentId);

      // Ждём, пока скрипт ЮKassa прогрузится
      const waitWidget = () =>
        new Promise(resolve => {
          const check = () => {
            if (window.YooMoneyCheckoutWidget) resolve();
            else setTimeout(check, 300);
          };
          check();
        });

      await waitWidget();

      // Открываем платежный виджет
      const widget = new window.YooMoneyCheckoutWidget({
        confirmation_token,
        return_url: "https://vk.com/app54348330", // Возврат в мини-апп
        error_callback: (error) => {
          alert("Ошибка: " + error.description);
        }
      });

      widget.render("yookassa-checkout"); // Модальное окно

    } catch (err) {
      console.error(err);
      alert("Ошибка при создании платежа");
    }

    setLoading(false);
  };

  return (
    <div id={id} className="panel-container">
      <div className="panel-title">Платёжный экран</div>
      <button className="button-main" onClick={handlePayment} disabled={loading}>
        {loading ? "Создаём..." : "Оплатить 990 ₽"}
      </button>

      {/* контейнер для модального окна */}
      <div id="yookassa-checkout"></div>

      <button className="button-secondary" onClick={() => go('subscribe')}>
        Назад
      </button>
    </div>
  );
};

export default Pay;
