import React, { useEffect, useState } from "react";
import axios from "axios";
import bridge from "@vkontakte/vk-bridge";

const PaymentCheck = ({ id, go }) => {
  const [statusMessage, setStatusMessage] = useState("Проверяем оплату...");

  useEffect(() => {
    const paymentId = localStorage.getItem("arina_payment_id");
    if (!paymentId) {
      setStatusMessage("Платёж не найден. Возвращаем на подписку...");
      setTimeout(() => go("subscribe"), 2000);
      return;
    }

    const checkPayment = async () => {
      try {
        const res = await axios.get(
          `https://ser-hyfd.onrender.com/payment-status/${paymentId}`
        );

        const status = res.data.status;

        if (status === "succeeded") {
          // рассчитываем дату окончания подписки
          const end = new Date();
          end.setMonth(end.getMonth() + 1);
          const endISO = end.toISOString();

          // сохраняем в VK Storage
          await bridge.send("VKWebAppStorageSet", {
            key: "arina_subscription_end",
            value: endISO,
          });

          setStatusMessage("Оплата прошла! Открываем чат...");
          setTimeout(() => go("chat"), 1200);
        } else if (status === "pending") {
          setStatusMessage("Платёж ожидает подтверждения...");
          setTimeout(checkPayment, 2500);
        } else {
          setStatusMessage("Платёж не прошёл.");
          setTimeout(() => go("subscribe"), 2000);
        }
      } catch (e) {
        console.error(e.response?.data || e.message);
        setStatusMessage("Ошибка проверки платежа.");
        setTimeout(() => go("subscribe"), 2000);
      }
    };

    checkPayment();
  }, [go]);

  return <div id={id} className="panel-container">{statusMessage}</div>;
};

export default PaymentCheck;
