import React, { useState } from 'react';

const SESSION_PRICE = 5000;
const DISCOUNT = 0.15;

const About = ({ id, go }) => {
  const [count, setCount] = useState(4);

  const regular = count * SESSION_PRICE;
  const withDiscount = Math.round(regular * (1 - DISCOUNT));

  return (
    <div id={id} className="panel-container">
      <div className="panel-title">Об ассистенте</div>

      <div className="panel-subtitle" style={{ lineHeight: 1.5 }}>
        Арина — ваш психологический ИИ-ассистент, который помогает справляться со стрессом, тревогой и эмоциональной усталостью.
      </div>

      <div className="panel-subtitle" style={{ marginTop: 15 }}>
        <b>Подписка даёт:</b><br />
        • Доступ к чату 24/7<br />
        • Персональные рекомендации<br />
        • Частичный анализ состояния<br />
        • Скидку 15% на консультации с живым психологом
      </div>

      <div className="panel-title" style={{ fontSize: 18, marginTop: 20 }}>Количество сессий со специалистом</div>

      <input
        type="number"
        min="1"
        value={count}
        onChange={(e) => setCount(Number(e.target.value))}
        style={{
          fontSize: 16,
          padding: 8,
          width: "60%",
          borderRadius: 8,
          border: "1px solid #bce6fd",
          marginBottom: 10,
          textAlign: "center"
        }}
      />

      <div className="panel-subtitle" style={{ fontSize: 14, lineHeight: 1.4 }}>
       Стоимость {withDiscount} ₽ со скидкой ({regular} ₽ без скидки)
      </div>

      <button
        className="button-main"
        onClick={() => go('subscribe')}
        style={{ marginTop: 15 }}
      >
        Оформить подписку
      </button>

      <button
        className="button-secondary"
        onClick={() => go('welcome')}
      >
        Вернуться на главную
      </button>
    </div>
  );
};

export default About;
