import React from 'react';

// Функция для генерации советов на основе ответов
const generateAdvice = (answers) => {
  const advice = {
    tension: [
      "Попробуйте дыхательные упражнения, чтобы успокоить ум.",
      "Небольшая прогулка на свежем воздухе помогает снять напряжение.",
      "Медитация или короткие паузы могут уменьшить стресс."
    ],
    fatigue: [
      "Сделайте небольшой сон или отдых, чтобы восстановить силы.",
      "Попробуйте лёгкую растяжку и дыхание для бодрости.",
      "Регулярные перерывы помогают снизить усталость."
    ],
    irritability: [
      "Сфокусируйтесь на дыхании, чтобы уменьшить раздражение.",
      "Запишите свои мысли, чтобы переработать эмоции.",
      "Постарайтесь отвлечься на приятное занятие."
    ],
    emptiness: [
      "Попробуйте записывать свои ощущения, чтобы понять причину пустоты.",
      "Сосредоточьтесь на маленьких радостях дня.",
      "Разговор с близким человеком помогает переработать эмоции."
    ],
    support: [
      "Я могу быть рядом 24/7, чтобы давать рекомендации и поддержку.",
      "Рассмотрите подписку для постоянной персональной поддержки."
    ]
  };

  let tips = [];

  // Вопрос 2 — что ощущается сильнее всего
  switch(answers[1]) {
    case 0: tips.push(advice.tension[0]); break; // Тревога
    case 1: tips.push(advice.fatigue[0]); break; // Усталость
    case 2: tips.push(advice.irritability[0]); break; // Раздражительность
    case 3: tips.push(advice.emptiness[0]); break; // Эмоциональное опустошение
    default: tips.push("Попробуйте расслабиться и прислушаться к себе.");
  }

  // Вопрос 4 — желание поддержки
  if(answers[3] === 0 || answers[3] === 1) tips.push(advice.support[0]);
  else tips.push(advice.support[1]);

  return tips;
};

const Result = ({ id, go, testAnswers }) => {
  const tips = generateAdvice(testAnswers);

  // Определяем краткий эмоциональный уровень
  const emotionalLevels = ["Низкая тревожность", "Средняя тревожность", "Повышенная тревожность", "Высокая тревожность"];
  const level = testAnswers[0] !== null ? emotionalLevels[testAnswers[0]] : "неопределённый";

  return (
    <div id={id} className="panel-container" style={{ background: "#f9eaff" }}>
      <div className="panel-title">Спасибо! Тест завершён</div>

      <div className="panel-subtitle" style={{ lineHeight: 1.5, marginBottom: 15 }}>
        <b>Ваш эмоциональный уровень:</b> {level}<br />
        {testAnswers[1] === 1 ? "Чувствуются симптомы усталости." : "Эмоциональный фон стабильный"}<br />
        <br />
        <b>Совет от Арины:</b>
        <ul style={{ textAlign: "left", paddingLeft: 20 }}>
          {tips.map((tip, i) => <li key={i}>{tip}</li>)}
        </ul>
        <br />
      </div>

      <button className="button-main" onClick={() => go('subscribe')} style={{ marginBottom: 10 }}>
        Оформить подписку
      </button>

      <button className="button-secondary" onClick={() => go('welcome')}>
        Вернуться на главную
      </button>
    </div>
  );
};

export default Result;
