import React, { useState, useEffect } from 'react';
import { View } from '@vkontakte/vkui';
import bridge from '@vkontakte/vk-bridge';

import Welcome from './panels/Welcome';
import Test from './panels/Test';
import Result from './panels/Result';
import About from './panels/About';
import Subscribe from './panels/Subscribe';
import Pay from './panels/Pay';
import Chat from './panels/Chat';
import PaymentCheck from './panels/PaymentCheck';
import SubscriptionExpired from './panels/SubscriptionExpired';

import './App.css';

const App = () => {
  const [activePanel, setActivePanel] = useState(null); // <-- стартуем без экрана
  const [testAnswers, setTestAnswers] = useState([]);

  // Инициализация + проверка подписки при запуске
  useEffect(() => {
    const init = async () => {
      await bridge.send('VKWebAppInit');

      try {
        // Читаем подписку из VK Storage
        const storage = await bridge.send("VKWebAppStorageGet", {
          keys: ["arina_subscription_end"]
        });

        const value = storage.keys[0]?.value;

        if (value) {
          const end = new Date(value);
          const now = new Date();

          if (end > now) {
            // подписка активна → сразу в чат
            setActivePanel('chat');
            return;
          }
        }
      } catch (e) {
        console.error("Ошибка загрузки подписки:", e);
      }

      // если нет подписки → на Welcome
      setActivePanel('welcome');
    };

    init();
  }, []);

  const go = (panel) => setActivePanel(panel);

  if (!activePanel) return null; // пока загружаем подписку — ничего не показываем

  return (
    <View activePanel={activePanel}>
      <Welcome id="welcome" go={go} />
      <Test id="test" go={go} setTestAnswers={setTestAnswers} />
      <Result id="result" go={go} testAnswers={testAnswers} />
      <About id="about" go={go} />
      <Subscribe id="subscribe" go={go} />
      <Pay id="pay" go={go} />
      <PaymentCheck id="paymentCheck" go={go} />
      <Chat id="chat" go={go} />
      <SubscriptionExpired id="subscriptionExpired" go={go} />
    </View>
  );
};

export default App;
